<script>
  export let authReady = false;
  export let profileLoading = false;
  export let isAdmin = false;
  export let currentRoute = 'admin';
  export let adminForm = { loginId: '', password: '', nickname: '', character: {} };
  export let accountSaving = false;
  export let createPlayerAccount = () => {};
  export let adminLoading = false;
  export let adminCharacters = [];
  export let selectAdminCharacter = () => {};
</script>

{#if !authReady || profileLoading}<section class="admin-page panel"><div class="empty-state"><span>◌</span><strong>관리자 권한을 확인하는 중이에요</strong><p>잠시만 기다려 주세요.</p></div></section>
{:else if !isAdmin}<section class="about-page panel"><p class="eyebrow">ACCESS RESTRICTED</p><h1>관리자 권한이<br /><em>필요합니다</em></h1><p class="about-lead">이 페이지는 캠페인 관리자만 이용할 수 있습니다.</p><a class="primary-btn about-button" href="#home">홈으로 돌아가기 <span>→</span></a></section>
{:else}<section class="admin-page panel"><div class="admin-shell"><nav class="admin-sidebar" aria-label="관리자 메뉴"><div class="admin-sidebar-brand"><span class="eyebrow">CONTROL ROOM</span><strong>관리자 메뉴</strong></div><a class:active={currentRoute === 'admin'} href="#admin"><span>◌</span><span><strong>플레이어 계정 생성</strong><small>ACCOUNTS &amp; CHARACTERS</small></span></a><a href="#admin/monsters"><span>♟</span><span><strong>몬스터 관리</strong><small>MONSTER CATALOG</small></span></a><a class:active={currentRoute === 'admin/items'} href="#admin/items"><span>◇</span><span><strong>아이템 관리</strong><small>ITEM CATALOG</small></span></a><a class:active={currentRoute === 'admin/shop'} href="#admin/shop"><span>G</span><span><strong>상점 상품 관리</strong><small>SHOP INVENTORY</small></span></a><a class:active={currentRoute === 'admin/combat-test'} href="#admin/combat-test"><span>⚔</span><span><strong>전투 테스트</strong><small>CARD DRAW LAB</small></span></a><a href="#combat"><span>⚔</span><span><strong>실시간 전투방</strong><small>CO-OP CARD BATTLE</small></span></a><div class="admin-sidebar-foot">운영 도구<br /><span>CAMPAIGN ADMIN</span></div></nav><div class="admin-shell-main"><div class="page-heading"><p class="eyebrow">CAMPAIGN ADMIN</p><h1>관리자 관리 페이지</h1><p>플레이어 계정과 마이페이지 정보를 관리합니다.</p></div><div class="admin-layout"><section class="admin-card"><div class="form-section-head"><div><p class="eyebrow">ADVENTURER ACCOUNTS</p><h2>플레이어 계정 생성</h2></div></div><form class="editor-form" on:submit|preventDefault={createPlayerAccount}><div class="field-grid"><label>로그인 아이디<input bind:value={adminForm.loginId} placeholder="플레이어 아이디" /></label><label>초기 비밀번호<input bind:value={adminForm.password} type="password" minlength="8" placeholder="8자 이상" /></label><label>표시 이름<input bind:value={adminForm.nickname} placeholder="플레이어 이름" /></label><label>캐릭터 이름<input bind:value={adminForm.character.name} placeholder="캐릭터 이름" /></label><label>역할명<input bind:value={adminForm.character.roleName} placeholder="역할명" /></label><label>나이<input bind:value={adminForm.character.age} type="number" min="0" placeholder="나이" /></label><label class="field-wide">역할 특징<textarea bind:value={adminForm.character.roleTraits} rows="3" placeholder="역할의 특징"></textarea></label><label>키 (cm)<input bind:value={adminForm.character.height} type="number" min="0" step="0.1" /></label><label>몸무게 (kg)<input bind:value={adminForm.character.weight} type="number" min="0" step="0.1" /></label></div><button class="primary-btn" type="submit" disabled={accountSaving}>{accountSaving ? '생성 중…' : '계정과 캐릭터 생성'} <span>↗</span></button></form><p class="form-note">로그인 아이디는 이메일 형식이나 영문·숫자 형식으로 제한하지 않습니다. 비밀번호만 8자 이상 입력해 주세요.</p></section><section class="admin-card"><div class="form-section-head"><div><p class="eyebrow">마이페이지 관리</p><h2>전체 캐릭터 목록</h2></div></div>{#if adminLoading}<div class="repeat-empty">목록을 불러오는 중이에요.</div>{:else if adminCharacters.length}{#each adminCharacters as item}<div class="character-list-item"><span class="avatar mint">{item.name.slice(0, 1)}</span><div><strong>{item.name}</strong><p>{item.nickname} · {item.role_name || '역할 미등록'}</p></div><span class="character-age">{item.age ? `${item.age}세` : '나이 미등록'}</span><button class="subtle-btn character-view-btn" type="button" on:click={() => selectAdminCharacter(item)}>상세보기</button></div>{/each}{:else}<div class="repeat-empty">아직 등록된 캐릭터가 없습니다.</div>{/if}</section></div></div></div></section>{/if}
